def transform(grid):
    h, w = len(grid), len(grid[0])
    values = {v for row in grid for v in row}

    # A plain panel with a distinctive corner marker reduces to that marker.
    if 8 in values and all(v in (2, 7, 8) for row in grid for v in row):
        return [[8]]

    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    base = max(counts, key=counts.get)

    # Markers lie on the grid lines; the most common color is the cell fill.
    marker_colors = values - {base}
    rs = [r for r in range(h) if sum(grid[r][c] in marker_colors for c in range(w)) >= 2]
    cs = [c for c in range(w) if sum(grid[r][c] in marker_colors for r in range(h)) >= 2]

    # Some patterns have an unmarked first vertical grid line.
    if len(cs) >= 3:
        gaps = [b - a for a, b in zip(cs, cs[1:])]
        if len(set(gaps)) == 1 and cs[0] == gaps[0]:
            cs = [0] + cs

    if len(rs) >= 2 and len(cs) >= 2:
        return [[grid[r][c] if grid[r][c] in marker_colors else base
                 for c in cs[:-1]] for r in rs[:-1]]
    return [[base]]
