def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    common = {v for v, _ in counts.most_common(2)}
    marker_colors = set(counts) - common

    # The plain framed example has a single corner marker.
    marker_positions = [(r, c) for r in range(h) for c in range(w)
                        if grid[r][c] in marker_colors]
    if len(marker_positions) <= 4 and len(marker_colors) == 1:
        return [[next(iter(marker_colors))]]

    rs = [r for r in range(h)
          if any(grid[r][c] in marker_colors for c in range(w))]
    cs = [c for c in range(w)
          if any(grid[r][c] in marker_colors for r in range(h))]

    if len(rs) < 2 or len(cs) < 2:
        return [[grid[marker_positions[0][0]][marker_positions[0][1]]]]

    # Cell interiors carry the default output color.
    centers = [
        grid[(r1 + r2) // 2][(c1 + c2) // 2]
        for r1, r2 in zip(rs, rs[1:])
        for c1, c2 in zip(cs, cs[1:])
    ]
    base = Counter(centers).most_common(1)[0][0]

    out = []
    for r1, r2 in zip(rs, rs[1:]):
        row = []
        for c1, c2 in zip(cs, cs[1:]):
            corners = (grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2])
            if corners[0] in marker_colors and all(x == corners[0] for x in corners):
                row.append(corners[0])
            else:
                row.append(base)
        out.append(row)
    return out
